import sys

data = sys.stdin.read().split()
n, q = int(data[0]), int(data[1])
positions = {}
for i in range(n):
    positions.setdefault(int(data[2 + i]), []).append(i + 1)
pos = 2 + n
for _ in range(q):
    l, k = int(data[pos]), int(data[pos + 1])
    pos += 2
    answer = 0
    for p in positions.values():
        if len(p) >= k and p[k - 1] <= l:
            answer += 1
    print(answer)
